import React, { useEffect, useState } from "react";
import "../styles/subscriptions.css";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [content, setContent] = useState([]); // зміст каналу: статті + опитування
  const [error, setError] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);

  const token = localStorage.getItem("token");

  // Завантаження поточного користувача
  useEffect(() => {
    if (!token) return;
    fetch("http://127.0.0.1:8000/api/users/me/", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then(setCurrentUser)
      .catch(console.error);
  }, [token]);

  // Завантаження каналів
  useEffect(() => {
    const fetchChannels = async () => {
      try {
        const res = await fetch("http://127.0.0.1:8000/api/channels/", {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        });
        if (!res.ok) throw new Error("Помилка завантаження каналів");
        const data = await res.json();
        setChannels(Array.isArray(data) ? data : data.results || []);
      } catch (err) {
        console.error(err);
        setError("Не вдалося завантажити канали");
      }
    };
    fetchChannels();
  }, [token]);

  // Відкрити канал і завантажити контент (статті + опитування)
  const openChannel = async (channelId) => {
    setSelectedChannel(channelId);
    setError(null);
    try {
      const [articlesRes, pollsRes] = await Promise.all([
        fetch(`http://127.0.0.1:8000/api/channels/${channelId}/articles/`, {
          headers: { "Content-Type": "application/json", ...(token && { Authorization: `Bearer ${token}` }) },
        }),
        fetch(`http://127.0.0.1:8000/api/channels/${channelId}/polls/`, {
          headers: { "Content-Type": "application/json", ...(token && { Authorization: `Bearer ${token}` }) },
        }),
      ]);

      if (!articlesRes.ok || !pollsRes.ok) throw new Error("Не вдалося завантажити контент каналу");

      const articles = await articlesRes.json();
      const polls = await pollsRes.json();

      // Додамо поле hasVoted для кожного опитування
      const pollsWithVoteStatus = polls.map((p) => ({
        ...p,
        contentType: "poll",
        created_at: p.created_at,
        hasVoted: p.votes_by_user?.includes(currentUser?.id) || false, // залежить від API
      }));

      const combined = [
        ...articles.map((a) => ({ ...a, contentType: "article", created_at: a.created_at || a.publish_date })),
        ...pollsWithVoteStatus,
      ].sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

      setContent(combined);
    } catch (err) {
      console.error(err);
      setError(err.message);
      setContent([]);
    }
  };

  const toggleSubscription = async (channelId, isSubscribed) => {
    try {
      const url = `http://127.0.0.1:8000/api/channels/${channelId}/${isSubscribed ? "unsubscribe" : "subscribe"}/`;
      const res = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json", ...(token && { Authorization: `Bearer ${token}` }) } });
      if (!res.ok) throw new Error("Помилка підписки");
      setChannels((prev) => prev.map((ch) => (ch.id === channelId ? { ...ch, is_subscribed: !isSubscribed } : ch)));
    } catch (err) {
      console.error(err);
      setError(err.message);
    }
  };

  // Голосування
  const handleVote = async (pollId, choiceId) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/polls/${pollId}/vote/${choiceId}/`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...(token && { Authorization: `Bearer ${token}` }) },
      });
      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || "Помилка голосування");
      }
      const updatedChoice = await res.json();

      setContent((prev) =>
        prev.map((item) => {
          if (item.contentType === "poll" && item.id === pollId) {
            return {
              ...item,
              choices: item.choices.map((c) =>
                c.id === choiceId ? { ...c, votes: updatedChoice.choice_votes } : c
              ),
              hasVoted: true, // приховуємо кнопку після голосу
            };
          }
          return item;
        })
      );
    } catch (err) {
      console.error(err);
      setError(err.message);
    }
  };

  // Видалення опитування (для адміна)
  const handleDeletePoll = async (pollId) => {
    if (!window.confirm("Видалити опитування?")) return;
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/polls/${pollId}/`, {
        method: "DELETE",
        headers: { "Content-Type": "application/json", ...(token && { Authorization: `Bearer ${token}` }) },
      });
      if (!res.ok) throw new Error("Не вдалося видалити опитування");
      setContent((prev) => prev.filter((item) => !(item.contentType === "poll" && item.id === pollId)));
    } catch (err) {
      console.error(err);
      setError(err.message);
    }
  };

  return (
    <div className="subscriptions-container">
      <h2>Підписки</h2>
      {error && <p className="error">{error}</p>}

      {!selectedChannel ? (
        <ul className="channel-list">
          {channels.length === 0 ? <p>Поки немає каналів</p> : channels.map((ch) => (
            <li key={ch.id} className="channel-item">
              <span className="channel-name" onClick={() => openChannel(ch.id)}>{ch.name || "Без назви"}</span>
              <button className={`subscribe-btn ${ch.is_subscribed ? "unsubscribe" : "subscribe"}`} onClick={() => toggleSubscription(ch.id, ch.is_subscribed)}>
                {ch.is_subscribed ? "Відписатись" : "Підписатись"}
              </button>
            </li>
          ))}
        </ul>
      ) : (
        <div>
          <button className="back-btn" onClick={() => setSelectedChannel(null)}>← Назад</button>
          <h3>Зміст каналу</h3>
          {content.length === 0 ? <p>Контент відсутній</p> : content.map((item) =>
            item.contentType === "article" ? (
              <div key={item.id} className="article-card">
                {item.image && <img src={item.image.startsWith("http") ? item.image : `http://127.0.0.1:8000${item.image}`} alt={item.title} className="article-image" />}
                <div className="article-content">
                  <h4>{item.title || "(Без назви)"}</h4>
                  <p>Автор: {item.author_name || "Невідомий"}</p>
                  {item.category && <p>Категорія: {item.category}</p>}
                  {item.created_at && <p>Опубліковано: {new Date(item.created_at).toLocaleDateString("uk-UA")}</p>}
                  <p>{item.content || "(Без контенту)"}</p>
                </div>
              </div>
            ) : (
              <div key={item.id} className="poll-card">
                <h4>Опитування: {item.question}</h4>
                {item.choices.map((c) => (
                  <div key={c.id} className="poll-choice">
                    <span>{c.text} — {c.votes} голосів</span>
                    {!item.hasVoted && <button onClick={() => handleVote(item.id, c.id)}>Голосувати</button>}
                  </div>
                ))}
                {currentUser?.is_staff && (
                  <button className="delete-poll-btn" onClick={() => handleDeletePoll(item.id)}>
                    Видалити опитування
                  </button>
                )}
              </div>
            )
          )}
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
